722	    @ViewBuilder
723	    private func projectedContent(
724	        _ projection: DockCardProjection,
725	        snapshot: DockSnapshot,
726	        revision: RenderRevision
727	    ) -> some View {
728	        VStack(alignment: .leading, spacing: 12) {
729	            if !projection.pinnedRows.isEmpty {
730	                DockPinnedSectionView(
731	                    projection: projection,
732	                    isCollapsed: $isPinnedCollapsed,
733	                    onMove: { rows in Task { await store.reorderPinnedRows(rows) } },
734	                    onUnpin: { row in Task { await store.setPinned(false, for: row) } },
735	                    onOpen: { row in openDetail(row: row) },
736	                    rowContent: { row in dockPinnedRow(row) }
737	                )
738	                if shouldShowPinnedBodyDivider(projection, snapshot: snapshot) {
739	                    Divider()
740	                        .codexAutomationID(AutomationID.Dock.pinnedBodyDivider)
741	                }
742	            } else if shouldShowPinnedHiddenHint(projection) {
743	                DockPinnedHiddenHintView(projection: projection, searchText: searchText)
744	                if shouldShowPinnedBodyDivider(projection, snapshot: snapshot) {
745	                    Divider()
746	                        .codexAutomationID(AutomationID.Dock.pinnedBodyDivider)
747	                }
748	            }
749	
750	            switch selectedLens {
751	            case .newest:
752	                LazyVStack(spacing: 10) {
753	                    ForEach(projection.rows) { row in
754	                        dockRow(row, resetToken: revision)
755	                    }
756	                    ForEach(contextualHostStates(in: snapshot)) { hostState in
757	                        hostContextRow(
758	                            hostState,
759	                            automationID: AutomationID.Dock.hostSummary(hostID: hostState.host.id)
760	                        )
761	                    }
762	                }
763	            case .host:
764	                LazyVStack(spacing: 12) {
765	                    ForEach(projection.groups) { group in
766	                        projectionGroup(
767	                            group,
768	                            collapsedIDs: $collapsedHostGroupIDs,
769	                            resetToken: revision
770	                        )
771	                    }
772	                }
773	            case .branch:
774	                LazyVStack(spacing: 12) {
775	                    ForEach(projection.groups) { group in
776	                        projectionGroup(
777	                            group,
778	                            collapsedIDs: $collapsedBranchGroupIDs,
779	                            resetToken: revision
780	                        )
781	                    }
782	                    ForEach(contextualHostStates(in: snapshot)) { hostState in
783	                        hostContextRow(
784	                            hostState,
785	                            automationID: AutomationID.Dock.hostSummary(hostID: hostState.host.id)
786	                        )
787	                    }
788	                }
789	            }
790	        }
791	    }
