  8	struct DockSwipeActionRow<Content: View>: View {
  9	    let row: DockRowViewModel
 10	    let actionID: AutomationID
 11	    let resetToken: RenderRevision
 12	    let onTogglePinned: () -> Void
 13	    let canOpen: Bool
 14	    let onOpen: () -> Void
 15	    @ViewBuilder var content: () -> Content
 16	    @State private var offset: CGFloat = 0
 17	
 18	    private let actionWidth: CGFloat = 86
 19	
 20	    var body: some View {
 21	        ZStack(alignment: .trailing) {
 22	            if offset != 0 {
 23	                swipeButton
 24	            }
 25	
 26	            content()
 27	                .offset(x: offset)
 28	        }
 29	        .contentShape(Rectangle())
 30	        .simultaneousGesture(dragGesture)
 31	        .onTapGesture(perform: handleTap)
 32	        .accessibilityElement(children: .contain)
 33	        .accessibilityLabel(row.title)
 34	        .accessibilityValue(row.automationValue)
 35	        .accessibilityAddTraits(canOpen ? .isButton : [])
 36	        .accessibilityAction {
 37	            handleTap()
 38	        }
 39	        .codexAutomationID(AutomationID.Dock.row(hostID: row.hostID, threadID: row.threadID))
 40	        // Parent ForEach owns row identity. Do not add a nested .id here;
 41	        // live reorders can otherwise leave stale duplicate accessibility rows.
 42	        .onChange(of: row.id) { _, _ in
 43	            closeAction(animated: false)
 44	        }
 45	        .onChange(of: row.isPinned) { _, _ in
 46	            closeAction(animated: false)
 47	        }
 48	        .onChange(of: resetToken) { _, _ in
 49	            closeAction(animated: false)
 50	        }
 51	        .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
 52	    }
 53	
 54	    private var dragGesture: some Gesture {
 55	        DragGesture(minimumDistance: 18, coordinateSpace: .local)
 56	            .onChanged(updateOffset)
 57	            .onEnded(finishDrag)
 58	    }
 59	
 60	    private var swipeButton: some View {
 61	        Button(role: row.isPinned ? .destructive : nil) {
 62	            closeAction()
 63	            onTogglePinned()
 64	        } label: {
 65	            Label(row.isPinned ? "Unpin" : "Pin", systemImage: row.isPinned ? "pin.slash" : "pin.fill")
 66	                .font(.caption.weight(.semibold))
 67	                .labelStyle(.titleAndIcon)
 68	                .frame(width: actionWidth)
 69	                .frame(maxHeight: .infinity)
 70	        }
 71	        .buttonStyle(.plain)
 72	        .foregroundStyle(.white)
 73	        .background(row.isPinned ? Color.red : Color.blue)
 74	        .codexAutomationID(actionID)
 75	    }
 76	
 77	    private func updateOffset(_ value: DragGesture.Value) {
 78	        guard abs(value.translation.width) > abs(value.translation.height) else {
 79	            return
 80	        }
 81	        offset = min(0, max(-actionWidth, value.translation.width))
 82	    }
 83	
 84	    private func finishDrag(_ value: DragGesture.Value) {
 85	        let shouldOpen = value.translation.width < -(actionWidth * 0.35)
 86	        withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
 87	            offset = shouldOpen ? -actionWidth : 0
 88	        }
 89	    }
 90	
 91	    private func handleTap() {
 92	        if offset != 0 {
 93	            closeAction()
 94	        } else if canOpen {
 95	            onOpen()
 96	        }
 97	    }
 98	
 99	    private func closeAction(animated: Bool = true) {
100	        // Render revisions are data updates. Do not open a spring transaction
101	        // unless there is an actual swipe offset to close; list reorders must
102	        // not leave duplicate accessibility rows during live updates.
103	        guard offset != 0 else {
104	            return
105	        }
106	        if animated {
107	            withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
108	                offset = 0
109	            }
110	        } else {
111	            offset = 0
112	        }
113	    }
114	}
