422	    private func hostStatus(
423	        freshness: DockStreamFreshnessDTO?,
424	        rowCount: Int,
425	        complete: Bool,
426	        totalRows: Int?
427	    ) -> DockHostLoadStatus {
428	        if !complete {
429	            let visibleRows = rowCount
430	            let knownTotal = max(totalRows ?? visibleRows, visibleRows)
431	            let message = knownTotal > visibleRows
432	                ? "Showing \(visibleRows) of \(knownTotal)"
433	                : "Partial window"
434	            return .partial(rowCount: visibleRows, message: message)
435	        }
436	        guard let freshness else {
437	            return rowCount == 0 ? .checking : .loaded(rowCount: rowCount)
438	        }
439	        switch freshness.status {
440	        case .fresh:
441	            return rowCount == 0 ? .empty : .loaded(rowCount: rowCount)
442	        case .stale:
443	            return .partial(rowCount: rowCount, message: freshness.lastError ?? "Stale")
444	        case .offline:
445	            let message = freshness.lastError ?? "Offline"
446	            return rowCount > 0 ? .partial(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
447	        case .error:
448	            let message = freshness.lastError ?? "Error"
449	            return rowCount > 0 ? .partial(rowCount: rowCount, message: message) : .error(message)
450	        case .unknown:
451	            return rowCount == 0 ? .checking : .partial(rowCount: rowCount, message: "Refreshing")
452	        }
453	    }
