448	    private func isComfortableSwipeFrame(_ frame: CGRect) -> Bool {
449	        let visibleFrame = primaryWindowFrame(defaultingTo: frame)
450	        let topInset: CGFloat = 96
451	        let bottomLimit = tabBars.firstMatch.exists
452	            ? tabBars.firstMatch.frame.minY - 12
453	            : visibleFrame.maxY - 96
454	        return frame.minY >= visibleFrame.minY + topInset
455	            && frame.maxY <= bottomLimit
456	    }
457	
458	    private func shouldScrollUp(toExpose frame: CGRect) -> Bool {
459	        frame.midY >= primaryWindowFrame(defaultingTo: frame).midY
460	    }
461	
462	    private func isVisibleForTap(_ frame: CGRect) -> Bool {
463	        guard frame.width > 1, frame.height > 1 else {
464	            return false
465	        }
466	        let visibleFrame = primaryWindowFrame(defaultingTo: frame)
467	        let bottomLimit = tabBars.firstMatch.exists
468	            ? tabBars.firstMatch.frame.minY - 1
469	            : visibleFrame.maxY - 1
470	        return frame.midY >= visibleFrame.minY + 1
471	            && frame.midY <= bottomLimit
472	            && frame.maxX > visibleFrame.minX
473	            && frame.minX < visibleFrame.maxX
474	    }
475	
476	    private func primaryWindowFrame(defaultingTo frame: CGRect) -> CGRect {
477	        let window = windows.firstMatch
478	        return window.exists ? window.frame : frame
479	    }
