 89	    private static func phase(from event: ConnectivityRuntimeEvent) -> HostConnectivityPhase {
 90	        let status = event.status.trimmingCharacters(in: .whitespacesAndNewlines)
 91	        let lowercased = status.lowercased()
 92	
 93	        if lowercased == "idle" {
 94	            return .unknown
 95	        }
 96	        if lowercased == "checking" || lowercased.hasPrefix("checking ") {
 97	            return .checking
 98	        }
 99	        if lowercased.hasPrefix("offline:") {
100	            return .offline(trimmedMessage(status, prefix: "offline:"))
101	        }
102	        if lowercased == "offline" {
103	            return .offline("Offline")
104	        }
105	        if lowercased.hasPrefix("error:") {
106	            return .error(trimmedMessage(status, prefix: "error:"))
107	        }
108	        if lowercased == "error" {
109	            return .error("Error")
110	        }
111	        if lowercased.contains("partial") {
112	            return .partial(status)
113	        }
114	        return .online(status.isEmpty ? "Online" : status)
115	    }
