 48	        }
 49	        if let status = firstStatus(hosts, matching: {
 50	            if case .backgrounded = $0.phase { return true }
 51	            return false
 52	        }) {
 53	            return .backgrounded("\(status.displayName): \(status.phase.message)")
 54	        }
 55	        if let status = firstStatus(hosts, matching: {
 56	            if case .resuming = $0.phase { return true }
 57	            return false
 58	        }) {
 59	            return .resuming("\(status.displayName): \(status.phase.message)")
 60	        }
 61	        if let status = firstStatus(hosts, matching: {
 62	            if case .reconnecting = $0.phase { return true }
 63	            return false
 64	        }) {
 65	            return .reconnecting("\(status.displayName): \(status.phase.message)")
 66	        }
 67	        if let status = firstStatus(hosts, matching: {
 68	            if case .stale = $0.phase { return true }
 69	            return false
 70	        }) {
 71	            return .stale("\(status.displayName): \(status.phase.message)")
 72	        }
 73	
 74	        let onlineLikeCount = hosts.filter { $0.phase.isOnlineLike }.count
 75	        let checkingCount = hosts.filter { status in
 76	            if case .checking = status.phase {
 77	                return true
