 83	    func setPinned(
 84	        _ isPinned: Bool,
 85	        for row: DockRowViewModel
 86	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
 87	        let key = row.metadataKey
 88	        var nextValues = PinnedMetadataOrdering.normalized(values)
 89	        var metadata = nextValues[key] ?? LocalThreadMetadata()
 90	        if isPinned {
 91	            let wasPinned = metadata.isPinned
 92	            metadata.isPinned = true
 93	            metadata.pinnedAt = metadata.pinnedAt ?? now()
 94	            if !wasPinned || metadata.pinnedOrder == nil {
 95	                metadata.pinnedOrder = PinnedMetadataOrdering.nextOrder(in: nextValues, excluding: key)
 96	            }
 97	        } else {
 98	            metadata.isPinned = false
 99	            metadata.pinnedAt = nil
100	            metadata.pinnedOrder = nil
101	        }
102	        nextValues[key] = metadata
103	        return try await save(metadataValues: PinnedMetadataOrdering.normalized(nextValues))
104	    }
105	
106	    func reorderPinnedRows(
107	        _ visibleRowsInNewOrder: [DockRowViewModel]
108	    ) async throws -> [LocalThreadMetadataKey: LocalThreadMetadata] {
109	        var nextValues = PinnedMetadataOrdering.normalized(values)
110	        let visibleKeys = PinnedMetadataOrdering.uniqueKeys(
111	            visibleRowsInNewOrder.map(\.metadataKey).filter { nextValues[$0]?.isPinned == true }
112	        )
113	        guard visibleKeys.count > 1 else {
114	            return nextValues
115	        }
116	
117	        let visibleKeySet = Set(visibleKeys)
118	        let orderedPinnedKeys = PinnedMetadataOrdering.orderedKeys(in: nextValues)
119	        var reorderedVisibleKeys = visibleKeys.makeIterator()
120	        let mergedKeys = orderedPinnedKeys.compactMap { key in
121	            if visibleKeySet.contains(key) {
122	                return reorderedVisibleKeys.next()
123	            }
124	            return key
125	        }
126	
127	        for (index, key) in mergedKeys.enumerated() {
128	            guard var metadata = nextValues[key], metadata.isPinned else {
129	                continue
130	            }
131	            metadata.pinnedOrder = index
132	            nextValues[key] = metadata
133	        }
134	        return try await save(metadataValues: nextValues)
135	    }

