 3	enum PinnedMetadataOrdering {
 4	    static func normalized(
 5	        _ values: [LocalThreadMetadataKey: LocalThreadMetadata]
 6	    ) -> [LocalThreadMetadataKey: LocalThreadMetadata] {
 7	        var normalized = values
 8	        for (index, key) in orderedKeys(in: values).enumerated() {
 9	            guard var metadata = normalized[key], metadata.isPinned else {
10	                continue
11	            }
12	            metadata.pinnedOrder = index
13	            normalized[key] = metadata
14	        }
15	        return normalized
16	    }
17	
18	    static func orderedKeys(
19	        in values: [LocalThreadMetadataKey: LocalThreadMetadata]
20	    ) -> [LocalThreadMetadataKey] {
21	        values
22	            .filter { $0.value.isPinned }
23	            .sorted(by: precedes)
24	            .map(\.key)
25	    }
26	
27	    static func nextOrder(
28	        in values: [LocalThreadMetadataKey: LocalThreadMetadata],
29	        excluding excludedKey: LocalThreadMetadataKey
30	    ) -> Int {
31	        let maxOrder = values
32	            .filter { $0.key != excludedKey && $0.value.isPinned }
33	            .compactMap(\.value.pinnedOrder)
34	            .max()
35	        return (maxOrder ?? -1) + 1
36	    }
37	
38	    static func uniqueKeys(_ keys: [LocalThreadMetadataKey]) -> [LocalThreadMetadataKey] {
39	        var seen = Set<LocalThreadMetadataKey>()
40	        var unique: [LocalThreadMetadataKey] = []
41	        for key in keys where !seen.contains(key) {
42	            seen.insert(key)
43	            unique.append(key)
44	        }
45	        return unique
46	    }
47	
48	    private static func precedes(
49	        _ lhs: (key: LocalThreadMetadataKey, value: LocalThreadMetadata),
50	        _ rhs: (key: LocalThreadMetadataKey, value: LocalThreadMetadata)
51	    ) -> Bool {
52	        if let lhsOrder = lhs.value.pinnedOrder,
53	           let rhsOrder = rhs.value.pinnedOrder,
54	           lhsOrder != rhsOrder {
55	            return lhsOrder < rhsOrder
56	        }
57	        if lhs.value.pinnedOrder != nil {
58	            return true
59	        }
60	        if rhs.value.pinnedOrder != nil {
61	            return false
62	        }
63	
64	        let lhsPinnedAt = lhs.value.pinnedAt ?? Date.distantPast
65	        let rhsPinnedAt = rhs.value.pinnedAt ?? Date.distantPast
66	        if lhsPinnedAt != rhsPinnedAt {
67	            return lhsPinnedAt < rhsPinnedAt
68	        }
69	
70	        return keyPrecedes(lhs.key, rhs.key)
71	    }
72	
73	    private static func keyPrecedes(_ lhs: LocalThreadMetadataKey, _ rhs: LocalThreadMetadataKey) -> Bool {
74	        [
75	            lhs.hostID,
76	            lhs.backendSessionID,
77	            lhs.threadID,
78	        ].joined(separator: "\u{1f}") < [
79	            rhs.hostID,
80	            rhs.backendSessionID,
81	            rhs.threadID,
82	        ].joined(separator: "\u{1f}")
83	    }
84	}

