37	    private func mapFailure(_ error: Error) -> DockRequestFailure {
38	        if let failure = error as? DockRequestFailure {
39	            return failure
40	        }
41	        if let clientError = error as? AppServerClientError {
42	            switch clientError {
43	            case .disconnected, .notConnected, .requestTimedOut, .transport:
44	                return .offline(clientError.localizedDescription)
45	            case .duplicateRequestID,
46	                 .malformedMessage,
47	                 .requestCancelled,
48	                 .responseDecoding,
49	                 .server,
50	                 .unexpectedServerRequest,
51	                 .unmatchedResponse:
52	                return .error(clientError.localizedDescription)
53	            }
54	        }
55	        return .error(error.localizedDescription)
